<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';const mode=ref('radial'),count=ref(8),radius=ref(82),angle=ref(0),playing=ref(false);let frame=0,last=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const modes=[{id:'radial',name:'旋转放射',note:'同一图元绕中心重复，形成向心与放射的节奏。'},{id:'mirror',name:'四向镜像',note:'沿两条轴线映照，比较方向与负形如何保持平衡。'},{id:'band',name:'二方连续',note:'图元沿一个方向反复延展，适合观察带状边饰的节奏。'},{id:'grid',name:'四方连续',note:'基本单元向上下左右延展，形成连续的平面秩序。'}];const units=computed(()=>{if(mode.value==='radial')return Array.from({length:count.value},(_,i)=>`translate(250 230) rotate(${i*360/count.value+angle.value}) translate(0 ${-radius.value}) scale(.7)`);if(mode.value==='mirror')return ['translate(250 230) scale(1 1)','translate(250 230) scale(-1 1)','translate(250 230) scale(1 -1)','translate(250 230) scale(-1 -1)'].map(s=>s+` rotate(${angle.value}) translate(45 -45) scale(.8)`);if(mode.value==='band')return Array.from({length:5},(_,i)=>`translate(${50+i*100} 230) rotate(${angle.value}) scale(.6)`);return Array.from({length:16},(_,i)=>`translate(${76+i%4*116} ${66+Math.floor(i/4)*110}) rotate(${angle.value+(i%2?45:0)}) scale(.48)`)});onMounted(()=>{function tick(t:number){frame=requestAnimationFrame(tick);if(playing.value&&!reduced&&t-last>45){angle.value=(angle.value+1)%360;last=t}}frame=requestAnimationFrame(tick)});onBeforeUnmount(()=>cancelAnimationFrame(frame));
</script><template><section class="symmetry-lab"><div class="section-title"><div><p class="kicker">A HANDS-ON PATTERN LESSON / 构图小实验</p><h2>亲手转一转，<em>秩序就出现了。</em></h2></div><span class="muted">改变规则，观察同一图元的不同表达</span></div><div class="symmetry-workbench"><div class="symmetry-canvas"><svg viewBox="0 0 500 460" aria-label="可交互的构图教学示意"><defs><pattern id="labGrid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#a3b78a" stroke-opacity=".15" stroke-width=".6"/></pattern><g id="lessonPetal"><path d="M0 -58 C-42 -45 -41 -9 0 0 C41 -9 42 -45 0 -58Z"/><path d="M0 -48V-9M-18 -37L0 -24L18 -37"/></g></defs><rect width="500" height="460" fill="url(#labGrid)"/><g class="lesson-guides"><circle cx="250" cy="230" r="155"/><circle cx="250" cy="230" r="100"/><path d="M250 20V440M20 230H480"/></g><use v-for="(unit,i) in units" :key="i" href="#lessonPetal" :transform="unit" :class="['lesson-petal',{alternate:i%2===1}]"/><circle cx="250" cy="230" r="4" fill="#bda16a"/><text x="20" y="440">构图教学示意 · 非文献原图</text></svg><div class="lesson-caption"><span>{{modes.find(m=>m.id===mode)?.name}}</span><button @click="playing=!playing" :disabled="reduced">{{playing?'Ⅱ 暂停观察':'▷ 看它转动'}}</button></div></div><aside><div class="lab-mode-grid"><button v-for="m in modes" :class="{active:mode===m.id}" @click="mode=m.id"><span>{{m.name}}</span><i>{{mode===m.id?'✓':'↗'}}</i></button></div><h3>规则不同，<br>图元的关系就不同。</h3><p :key="mode">{{modes.find(m=>m.id===mode)?.note}}</p><label v-if="mode==='radial'">重复数量 <span>{{count}} 向</span><input type="range" v-model.number="count" min="4" max="12" step="1"></label><label v-if="mode==='radial'">离心距离 <span>{{radius}}</span><input type="range" v-model.number="radius" min="25" max="135" step="5"></label><label>图元转角 <span>{{Math.round(angle)}}°</span><input type="range" v-model.number="angle" min="0" max="360" step="1"></label><p class="lab-caution">构图改变的是形式关系；一种新排列是否具有特定文化寓意，还需要另找证据。</p></aside></div></section></template>
